-- petlove: schema inicial PostgreSQL (Supabase)
-- Execute no SQL Editor do projeto Supabase. Não contém credenciais.
create extension if not exists pgcrypto;

create table if not exists public.products (
 id bigint generated by default as identity primary key,
 name text not null, cat text not null, pet text not null,
 price numeric(12,2) not null check(price >= 0), old numeric(12,2),
 rating numeric(3,2) not null default 5, reviews integer not null default 0,
 img text not null, tag text, description text not null default '',
 specs jsonb not null default '{}'::jsonb, stock integer, sku text unique,
 featured boolean not null default false, active boolean not null default true,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.orders (
 id uuid primary key, code text unique not null, customer jsonb not null, address jsonb not null, items jsonb not null,
 subtotal numeric(12,2) not null, discount numeric(12,2) not null, shipping numeric(12,2) not null, total numeric(12,2) not null,
 coupon text, payment_method text not null, payment_status text not null default 'pending',
 fulfillment_status text not null default 'received', tracking_code text, mp_preference_id text,
 created_at timestamptz not null default now(), archived_at timestamptz
);
create table if not exists public.order_events (
 id bigint generated by default as identity primary key, order_id uuid not null references public.orders(id) on delete cascade,
 status text not null, description text not null, created_at timestamptz not null default now()
);
create table if not exists public.contacts (id bigint generated by default as identity primary key, name text, email text, subject text, message text, created_at timestamptz default now());
create table if not exists public.subscribers (id bigint generated by default as identity primary key, email text unique, created_at timestamptz default now());
create table if not exists public.bookings (id bigint generated by default as identity primary key, name text, email text, phone text, pet text, service text, date date, slot text, status text default 'requested', created_at timestamptz default now(), unique(date,slot));
create table if not exists public.webhook_events (id bigint generated by default as identity primary key, event_id text unique, payload jsonb, created_at timestamptz default now());
create table if not exists public.admins (id bigint generated by default as identity primary key, email text unique not null, password_hash text not null, created_at timestamptz not null default now());
create table if not exists public.admin_sessions (token_hash text primary key, admin_id bigint not null references public.admins(id) on delete cascade, expires_at timestamptz not null, created_at timestamptz not null default now());

-- O backend deve acessar estas tabelas exclusivamente com credencial server-side.
alter table public.products enable row level security;
alter table public.orders enable row level security;
alter table public.order_events enable row level security;
alter table public.contacts enable row level security;
alter table public.subscribers enable row level security;
alter table public.bookings enable row level security;
alter table public.webhook_events enable row level security;
alter table public.admins enable row level security;
alter table public.admin_sessions enable row level security;

-- Bucket para imagens de produtos. Arquivos públicos para exibição no catálogo.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('petlove-products','petlove-products',true,5242880,array['image/jpeg','image/png','image/webp'])
on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
insert into public.products(id,name,cat,pet,price,old,rating,reviews,img,tag,description,specs,stock,sku,featured,active) select x.id,x.name,x.cat,x.pet,x.price,x.old,x.rating,x.reviews,x.img,x.tag,x.description,x.specs,x.stock,x.sku,x.featured,x.active from jsonb_to_record('{"id": 1, "name": "Corda Mordedora Duo", "cat": "brinquedos", "pet": "cao", "price": 39.9, "old": 49.9, "rating": 4.8, "reviews": 212, "img": "brinquedo-corda.webp", "tag": "Top", "description": "Corda de algodão trançado com dupla textura que ajuda na limpeza dos dentes e gasta energia de forma saudável.", "specs": {"Material": "Algodão natural", "Porte": "Médio/Grande", "Peso": "180 g", "Garantia": "30 dias"}, "stock": null, "sku": "PL-0001", "featured": false, "active": true}'::jsonb) as x(id bigint,name text,cat text,pet text,price numeric,old numeric,rating numeric,reviews integer,img text,tag text,description text,specs jsonb,stock integer,sku text,featured boolean,active boolean) where not exists(select 1 from public.products where id=x.id);
